using System;
class InvisibilityChecks {
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);}
 static void Main(){var e=new SenseEffects();e.NormalInvisibility(true,0);e.NormalInvisibility(false,0);long first=e.Token(true,0);Check(e.Invisible(true,0)&&e.Invisible(false,0),"multiple targets initially invisible");Check(e.BreakNormal(true,0,first)&&!e.Invisible(true,0)&&e.Invisible(false,0),"attack/cast trigger only breaks actor");Check(!e.BreakNormal(true,0,first),"repeated trigger has no effect");e.NormalInvisibility(true,0);long old=e.Token(true,0);e.EndConcentration();e.NormalInvisibility(true,0);Check(!e.BreakNormal(true,0,old)&&e.Invisible(true,0),"casting a new invisibility never clears fresh effect with stale token");Check(!e.BreakNormal(true,0,0)&&e.Invisible(true,0),"no prior invisibility does not break newly cast spell");Check(e.NormalInvisible(true,599)&&!e.NormalInvisible(true,600),"one hour duration");e.Clear();e.GreaterInvisible(true,0);Check(!e.BreakNormal(true,0,e.Token(true,0))&&e.Invisible(true,0),"greater invisibility unaffected");e.Clear();e.NormalInvisibility(true,0);e.NormalInvisibility(false,0);var c=new CombatState();c.DamageDealt=source=>e.BreakNormal(source,0,e.Token(source,0));c.ApplyPlayerDamage(1);Check(e.Invisible(true,0)&&!e.Invisible(false,0),"monster damage reveals source rather than victim");e.NormalInvisibility(false,0);c.ApplyPlayerDamage(1,sourcePlayer:true);Check(!e.Invisible(true,0)&&e.Invisible(false,0),"self inflicted player spell damage reveals player rather than monster");e.NormalInvisibility(true,0);c.GrantMonsterTemporaryHp(5);c.ApplyDamage(1);Check(!e.Invisible(true,0)&&e.Invisible(false,0)&&c.Hp==1000,"temporary hp absorption still counts as damage dealt");e.NormalInvisibility(true,0);c.ApplyDamage(0);Check(e.Invisible(true,0),"zero damage does not trigger damage event");c=new CombatState();c.DamageDealt=source=>e.BreakNormal(source,0,e.Token(source,0));c.DeathWardGuard=target=>true;c.ApplyPlayerDamage(100,sourcePlayer:true);Check(c.PlayerHp==1&&!e.Invisible(true,0),"damage ending invisibility is notified on death ward early return");e.EndConcentration();Check(!e.AnyNormal(0),"concentration clears all targets");Console.WriteLine("PASS: per-target invisibility, casting generations, expiry, greater invisibility, damage ownership, temp hp, zero damage and death ward");}
}
